import hashlib
import hmac
import os
import time

BACKEND_SECRET = os.getenv("BACKEND_SECRET", "")


def verify_user_token(email: str, token: str) -> bool:
    """Verify a signed token generated by the Next.js /api/auth-token route.

    Token format: {timestamp_ms}:{hmac_sha256(email:timestamp_ms, BACKEND_SECRET)}
    Valid for 5 minutes. If BACKEND_SECRET is unset (local dev), always passes.
    """
    if not BACKEND_SECRET:
        return True
    try:
        timestamp_str, sig = token.split(":", 1)
        timestamp_ms = int(timestamp_str)
        if abs(time.time() * 1000 - timestamp_ms) > 5 * 60 * 1000:
            return False
        expected = hmac.new(
            BACKEND_SECRET.encode(),
            f"{email}:{timestamp_str}".encode(),
            hashlib.sha256,
        ).hexdigest()
        return hmac.compare_digest(expected, sig)
    except Exception:
        return False
